//! Port of `sac_tsd.h` and `sac_tsd.cpp`: the transient steering decorrelator (TSD) of USAC
//! MPS212.
//!
//! The tables are generated by `sac_rom/gen_tables.py` ([`tables`]).

pub mod tables;
pub use tables::*;

use fdk_aac_rs_fdk::bitstream::{fdk_read_bit, fdk_read_bits, FdkBitStream};
use fdk_aac_rs_fdk::common_fix::*;
use fdk_aac_rs_fdk::fdk_assert;
use fdk_aac_rs_fdk::scale::saturate_left_shift;

/// `MAX_TSD_TIME_SLOTS`
pub const MAX_TSD_TIME_SLOTS: usize = 64;

/// `TSD_START_BAND`
const TSD_START_BAND: usize = 7;
/// `SIZE_S`
const SIZE_S: usize = 4;
/// `SIZE_C`
const SIZE_C: usize = 5;

/// `TSD_DATA`: the data needed to apply TSD to the current frame.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct TsdData {
    /// `bsTsdEnable`: for the current frame TSD is (0: disabled, 1: enabled)
    pub bs_tsd_enable: u8,
    /// `numSlots`: total number of QMF slots per frame
    pub num_slots: u8,
    /// `bsTsdTrPhaseData[MAX_TSD_TIME_SLOTS]`: -1 => TsdSepData`ts` = 0; 0-7: values of
    /// bsTsdTrPhaseData`ts` and TsdSepData`ts` = 1
    pub bs_tsd_tr_phase_data: [i8; MAX_TSD_TIME_SLOTS],
}

impl Default for TsdData {
    fn default() -> Self {
        TsdData { bs_tsd_enable: 0, num_slots: 0, bs_tsd_tr_phase_data: [0; MAX_TSD_TIME_SLOTS] }
    }
}

/// `isTsdActive(pTsdData)`
#[inline]
pub fn is_tsd_active(p_tsd_data: &TsdData) -> i32 {
    p_tsd_data.bs_tsd_enable as i32
}

/// `longmult1(a, b, d, len)`: `d = a * b` (in place: `a` and `d` are the same array in every
/// call of the library).
fn longmult1(a: &mut [u16; SIZE_C], b: u16, len: usize) {
    let b0 = b as u32;
    let mut tmp = (a[0] as u32).wrapping_mul(b0);
    a[0] = tmp as u16;
    for k in 1..len {
        tmp = (tmp >> 16).wrapping_add((a[k] as u32).wrapping_mul(b0));
        a[k] = tmp as u16;
    }
}

/// `longdiv(b, a, d, pr, len)`: `d = b / a`, `*pr = b % a` (in place: `b` and `d` are the same
/// array in every call of the library).
///
/// Deviation: `a == 0` has no defined result in C (never passed by the library: the divisors
/// are `2..=p` and `k >= 1`); the port leaves the digits unchanged and returns 0.
fn longdiv(b: &mut [u16; SIZE_C], a: u16, len: usize) -> u16 {
    fdk_assert!(a != 0);
    if a == 0 {
        return 0;
    }
    let mut r: u32 = 0;
    for k in (0..len).rev() {
        let tmp = (b[k] as u32).wrapping_add(r << 16);
        if tmp != 0 {
            b[k] = (tmp / a as u32) as u16;
            r = tmp.wrapping_sub((b[k] as u32).wrapping_mul(a as u32));
        } else {
            b[k] = 0;
        }
    }
    r as u16
}

/// `longsub(a, b, lena, lenb)`: `a -= b`.
fn longsub(a: &mut [u16; SIZE_S], b: &[u16; SIZE_C], lena: usize, lenb: usize) {
    let mut carry: i32 = 0;
    fdk_assert!(lena >= lenb);
    let mut h = 0;
    while h < lenb {
        carry = carry.wrapping_add(a[h] as i32 - b[h] as i32);
        a[h] = carry as u16;
        carry >>= 16;
        h += 1;
    }
    while h < lena {
        carry = (a[h] as i32).wrapping_add(carry);
        a[h] = carry as u16;
        carry >>= 16;
        h += 1;
    }
    fdk_assert!(carry == 0); // carry != 0 indicates subtraction underflow, e.g. b > a
}

/// `longcompare(a, b, len)`: `a >= b`.
fn longcompare(a: &[u16; SIZE_S], b: &[u16; SIZE_C], len: usize) -> i32 {
    let mut i = len - 1;
    while i > 0 {
        if a[i] != b[i] {
            break;
        }
        i -= 1;
    }
    (a[i] >= b[i]) as i32
}

/// `isTrSlot(pTsdData, ts)`
#[inline]
fn is_tr_slot(p_tsd_data: &TsdData, ts: i32) -> bool {
    // ts is in 0..MAX_TSD_TIME_SLOTS in every call of the library.
    p_tsd_data.bs_tsd_tr_phase_data.get(ts as usize).is_some_and(|&v| v >= 0)
}

/// `TsdRead(hBs, numSlots, pTsdData)`: parses and decodes the TSD data. Returns 0 on success,
/// 1 on error.
pub fn tsd_read(h_bs: &mut FdkBitStream, num_slots: i32, p_tsd_data: &mut TsdData) -> i32 {
    let n_bits_tr_slots;
    let n_bits_tsd_cw_tab: &[u8];

    match num_slots {
        32 => {
            n_bits_tr_slots = 4;
            n_bits_tsd_cw_tab = &N_BITS_TSD_CW_32SLOTS;
        }
        64 => {
            n_bits_tr_slots = 5;
            n_bits_tsd_cw_tab = &N_BITS_TSD_CW_64SLOTS;
        }
        _ => return 1,
    }

    // Read TempShapeData for bsTempShapeConfig == 3
    p_tsd_data.bs_tsd_enable = fdk_read_bit(h_bs) as u8;
    if p_tsd_data.bs_tsd_enable == 0 {
        return 0;
    }

    // Parse/Decode TsdData()
    p_tsd_data.num_slots = num_slots as u8;

    let bs_tsd_num_tr_slots = fdk_read_bits(h_bs, n_bits_tr_slots) as i32;

    // Decode transient slot positions
    {
        let mut n_bits_tsd_cw = n_bits_tsd_cw_tab[bs_tsd_num_tr_slots as usize] as i32;
        let phase_data = &mut p_tsd_data.bs_tsd_tr_phase_data;
        let mut p = bs_tsd_num_tr_slots + 1;
        let mut s = [0u16; SIZE_S];
        let mut c = [0u16; SIZE_C];

        // Init with TsdSepData[k] = 0
        for k in 0..num_slots as usize {
            phase_data[k] = -1; // means TsdSepData[] = 0
        }

        for h in (0..SIZE_S as i32).rev() {
            if n_bits_tsd_cw > h * 16 {
                s[h as usize] = fdk_read_bits(h_bs, (n_bits_tsd_cw - h * 16) as u32) as u16;
                n_bits_tsd_cw = h * 16;
            }
        }

        // c = prod_{h=1}^{p} (k-p+h)/h
        let mut k = num_slots - 1;
        c[0] = (k - p + 1) as u16;
        for h in 2..=p {
            longmult1(&mut c, (k - p + h) as u16, 5); // c *= k - p + h;
            let _r = longdiv(&mut c, h as u16, 5); // c /= h;
            fdk_assert!(_r == 0);
        }

        // go through all slots
        while k >= 0 {
            if p > k {
                while k >= 0 {
                    phase_data[k as usize] = 1; // means TsdSepData[] = 1
                    k -= 1;
                }
                break;
            }
            if longcompare(&s, &c, 4) != 0 {
                // (s >= c)
                longsub(&mut s, &c, 4, 4); // s -= c;
                phase_data[k as usize] = 1; // means TsdSepData[] = 1
                if p == 1 {
                    break;
                }
                // Update c for next iteration: c_new = c_old * p / k
                longmult1(&mut c, p as u16, 5);
                p -= 1;
            } else {
                // Update c for next iteration: c_new = c_old * (k-p) / k
                longmult1(&mut c, (k - p) as u16, 5);
            }
            let _r = longdiv(&mut c, k as u16, 5);
            fdk_assert!(_r == 0);
            k -= 1;
        }

        // Read phase data
        for k in 0..num_slots as usize {
            if phase_data[k] == 1 {
                phase_data[k] = fdk_read_bits(h_bs, 3) as i8;
            }
        }
    }

    0
}

/// Where the allpass based decorrelator reads from, as set by [`tsd_generate_non_tr`]
/// (`*ppDecorrInReal`, `*ppDecorrInImag`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TsdDecorrInput {
    /// The direct signal (`pVdirectReal`, `pVdirectImag`).
    Direct,
    /// The non-transient signal (`pVnonTrReal`, `pVnonTrImag`).
    NonTr,
}

/// `TsdGenerateNonTr(numHybridBands, pTsdData, ts, pVdirectReal, pVdirectImag, pVnonTrReal,
/// pVnonTrImag, ppDecorrInReal, ppDecorrInImag)`: transient separation (the `v_{x,nonTr}`
/// signal). Returns which signal the allpass based decorrelator reads from.
pub fn tsd_generate_non_tr(
    num_hybrid_bands: i32,
    p_tsd_data: &TsdData,
    ts: i32,
    p_vdirect_real: &[FixpDbl],
    p_vdirect_imag: &[FixpDbl],
    p_vnon_tr_real: &mut [FixpDbl],
    p_vnon_tr_imag: &mut [FixpDbl],
) -> TsdDecorrInput {
    if !is_tr_slot(p_tsd_data, ts) {
        // Let allpass based decorrelator read from direct input.
        return TsdDecorrInput::Direct;
    }

    // Generate nonTr input signal for allpass based decorrelator
    let n = num_hybrid_bands.max(0) as usize;
    let mut k = 0;
    while k < TSD_START_BAND {
        p_vnon_tr_real[k] = p_vdirect_real[k];
        p_vnon_tr_imag[k] = p_vdirect_imag[k];
        k += 1;
    }
    while k < n {
        p_vnon_tr_real[k] = 0;
        p_vnon_tr_imag[k] = 0;
        k += 1;
    }
    TsdDecorrInput::NonTr
}

/// `TsdApply(numHybridBands, pTsdData, pTsdTs, pVdirectReal, pVdirectImag, pDnonTrReal,
/// pDnonTrImag)`: generates the `d_{x,Tr}` signal and adds it to the `d_{x,nonTr}` signal.
pub fn tsd_apply(
    num_hybrid_bands: i32,
    p_tsd_data: &TsdData,
    p_tsd_ts: &mut i32,
    p_vdirect_real: &[FixpDbl],
    p_vdirect_imag: &[FixpDbl],
    p_dnon_tr_real: &mut [FixpDbl],
    p_dnon_tr_imag: &mut [FixpDbl],
) {
    let ts = *p_tsd_ts;

    if is_tr_slot(p_tsd_data, ts) {
        let idx = p_tsd_data.bs_tsd_tr_phase_data[ts as usize];
        fdk_assert!((0..8).contains(&idx));
        // idx is in 0..=7: a positive value of bsTsdTrPhaseData is always a 3 bit value.
        let phi = PHI_TSD[(idx & 7) as usize];

        // d = d_nonTr + v_direct * exp(j * bsTsdTrPhaseData[ts]/4 * pi )
        for k in TSD_START_BAND..num_hybrid_bands.max(0) as usize {
            let (temp_real, temp_imag) =
                cplx_mult_div2(p_vdirect_real[k], p_vdirect_imag[k], phi[0], phi[1]);
            p_dnon_tr_real[k] = saturate_left_shift(
                (p_dnon_tr_real[k] >> 2).wrapping_add(temp_real >> 1),
                2,
                DFRACT_BITS,
            );
            p_dnon_tr_imag[k] = saturate_left_shift(
                (p_dnon_tr_imag[k] >> 2).wrapping_add(temp_imag >> 1),
                2,
                DFRACT_BITS,
            );
        }
    }

    // The modulo MAX_TSD_TIME_SLOTS operation is to avoid illegal memory accesses in case of
    // errors.
    *p_tsd_ts = (ts + 1) & (MAX_TSD_TIME_SLOTS as i32 - 1);
}
